'use strict';

// MODULES //

var isLayout = require( '@stdlib/blas/base/assert/is-layout' );
var format = require( '@stdlib/string/format' );
var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major-string' );
var max = require( '@stdlib/math/base/special/fast/max' );
var base = require( './base.js' );


// MAIN //

/**
* Compute a LQ factorization of a real M-by-N matrix `A`.
*
* ## Notes
*
* -   On exit, the elements on and below the diagonal of the array contain the `m-by-min(m,n)` lower trapezoidal matrix `L` (`L` is lower triangular if `m <= n`).
* -   On exit, the elements above the diagonal, with the array `TAU`, represent the orthogonal matrix `Q` as a product of elementary reflectors.
* -   `LWORK >= 1`, if `MIN(M,N) = 0`, and `LWORK >= M`, otherwise. For optimum performance `LWORK >= M*NB`, where `NB` is the optimal blocksize.
* -   If `LWORK = -1`, then a workspace query is assumed; the routine only calculates the optimal size of the `WORK` array, returns this value as the first entry of the `WORK` array
*
* @param {string} order - storage layout
* @param {NonNegativeInteger} M - number of rows in `A`
* @param {NonNegativeInteger} N - number of columns in `A`
* @param {Float64Array} A - input/output matrix
* @param {integer} LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param {Float64Array} TAU - output array of scalar factors (length `min(M,N)`)
* @param {Float64Array} WORK - workspace array (length >= `M`)
* @param {NonNegativeInteger} LWORK - dimension of the array `WORK`
* @throws {TypeError} first argument must be a valid order
* @throws {RangeError} second argument must be a non-negative integer
* @throws {RangeError} third argument must be a non-negative integer
* @throws {RangeError} fifth argument must be a valid `LDA` value
* @throws {RangeError} eight argument must be a valid `LWORK` value
* @returns {integer} status code (0 if successful)
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
* var TAU = new Float64Array( 3 );
* var WORK = new Float64Array( 4 );
*
* dgelqf( 'column-major', 3, 4, A, 3, TAU, WORK, 4 );
* // A => <Float64Array>[ ~-5.477, ~-12.78, ~-20.083, ~0.309, ~-3.266, ~-6.532, ~0.463, ~-0.327, ~0.0, ~0.618, ~-0.789, ~0.618 ]
* // TAU => <Float64Array>[ ~1.183, ~1.156, ~1.447 ]
* // WORK => <Float64Array>[ 3.0, ~24.593, 0.0, 0.0 ]
*/
function dgelqf( order, M, N, A, LDA, TAU, WORK, LWORK ) {  // eslint-disable-line stdlib/jsdoc-doctest-decimal-point
	var sa1;
	var sa2;

	if ( !isLayout( order ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	if ( M < 0 ) {
		throw new RangeError( format( 'invalid argument. Second argument must be a nonnegative integer. Value: `%d`.', M ) );
	}
	if ( N < 0 ) {
		throw new RangeError( format( 'invalid argument. Third argument must be a nonnegative integer. Value: `%d`.', N ) );
	}
	if ( isRowMajor( order ) ) {
		if ( LDA < max( 1, N ) ) {
			throw new RangeError( format( 'invalid argument. Fifth argument must be greater than or equal to `max(1,N)`. Value: `%d`.', LDA ) );
		}
	} else if ( LDA < max( 1, M ) ) {
		throw new RangeError( format( 'invalid argument. Fifth argument must be greater than or equal to `max(1,M)`. Value: `%d`.', LDA ) );
	}
	if ( LWORK !== -1 && ( LWORK <= 0 || ( N > 0 && LWORK < max( 1, M ) ) ) ) {
		throw new RangeError( format( 'invalid argument. Eighth argument must be a valid LWORK value. Value: `%d`.', LWORK ) );
	}
	if ( order === 'column-major' ) {
		sa1 = 1;
		sa2 = LDA;
	} else {
		sa1 = LDA;
		sa2 = 1;
	}
	return base( M, N, A, sa1, sa2, 0, TAU, 1, 0, WORK, 1, 0, LWORK );
}


// EXPORTS //

module.exports = dgelqf;
